2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
13	 * firstName, lastName, address, city or telephone, listing every offending field. On success it
14	 * republishes the body for {@link BuildOwner}, which is the only other reader of the request.
15	 */
16	public class RequireOwnerFields {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws MissingOwnerFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        require(missing, "firstName", request.getFirstName());
22	        require(missing, "lastName", request.getLastName());
23	        require(missing, "address", request.getAddress());
24	        require(missing, "city", request.getCity());
25	        require(missing, "telephone", request.getTelephone());
26	        if (!missing.isEmpty()) {
27	            throw new MissingOwnerFieldsException(missing);
28	        }
29	        validated.set(request);
30	    }
31	
32	    private static void require(List<String> missing, String field, String value) {
33	        if (value == null || value.isBlank()) {
34	            missing.add(field);
35	        }
36	    }
37	}
