1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Runs after {@link RequireOwnerFields} on {@code POST /api/owners}: strips every non-digit
9	 * character from the telephone and requires exactly ten digits, replacing the field in place
10	 * (so {@link BuildOwner} maps the normalized value). A telephone that is not exactly ten digits
11	 * after stripping is rejected with 400 via {@link InvalidTelephoneException}.
12	 */
13	public class NormalizeOwnerTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
16	        String raw = request.getTelephone();
17	        String digits = raw == null ? "" : raw.replaceAll("\\D", "");
18	        if (digits.length() != 10) {
19	            throw new InvalidTelephoneException(raw);
20	        }
21	        request.setTelephone(digits);
22	    }
23	}
